  CREATE   PROCEDURE [Mapping].[usp_MergeLegacyEnriched]      @chrEntity    SYSNAME,      @chrGroupCode NVARCHAR(50),      @payload      NVARCHAR(MAX)  AS  BEGIN      SET NOCOUNT ON;        DECLARE @msg NVARCHAR(400);        ------------------------------------------------------------------      -- Guard 1: entity must exist as a schema in dp_legacy      ------------------------------------------------------------------      IF NOT EXISTS (SELECT 1 FROM dp_legacy.sys.schemas WHERE name = @chrEntity)      BEGIN          SET @msg = N'Entity schema ' + @chrEntity + N' does not exist in dp_legacy.';          THROW 50001, @msg, 1;      END;        ------------------------------------------------------------------      -- Guard 2: group code must be supplied and exist in the entity Legacy      ------------------------------------------------------------------      IF NULLIF(LTRIM(RTRIM(@chrGroupCode)), N'') IS NULL      BEGIN          THROW 50002, N'Group code is required.', 1;      END;        -- Group code is scoped by the code prefix: <groupcode>_<source key>      DECLARE @pat NVARCHAR(60) = LTRIM(RTRIM(@chrGroupCode)) + N'\_%';      DECLARE @esc NCHAR(1)     = N'\';      DECLARE @tgt NVARCHAR(300) = N'dp_legacy.' + QUOTENAME(@chrEntity) + N'.Legacy';      DECLARE @cnt INT;      DECLARE @chk NVARCHAR(MAX) =          N'SELECT @c = COUNT(*) FROM ' + @tgt + N' WHERE [code] LIKE @pat ESCAPE @esc;';        EXEC sp_executesql @chk, N'@pat NVARCHAR(60), @esc NCHAR(1), @c INT OUTPUT', @pat = @pat, @esc = @esc, @c = @cnt OUTPUT;        IF @cnt = 0      BEGIN          SET @msg = N'Group code ' + @chrGroupCode + N' has no rows in entity ' + @chrEntity + N'.';          THROW 50003, @msg, 1;      END;        ------------------------------------------------------------------      -- Static SQL: parse the /enrich response into a temp table      ------------------------------------------------------------------      IF OBJECT_ID(N'tempdb..#src') IS NOT NULL DROP TABLE #src;        SELECT *      INTO #src      FROM OPENJSON(@payload, N'$.results')      WITH (          [Customer]          NVARCHAR(100) N'$."Customer"',          [Name 1]            NVARCHAR(255) N'$."Name 1"',          [Name 2]            NVARCHAR(255) N'$."Name 2"',          [Name 3]            NVARCHAR(255) N'$."Name 3"',          [Name 4]            NVARCHAR(255) N'$."Name 4"',          [Domain]            NVARCHAR(255) N'$."Domain"',          [Department Domain] NVARCHAR(255) N'$."Department Domain"',          [Search Term 1]     NVARCHAR(255) N'$."Search Term 1"',          [Search Term 2]     NVARCHAR(255) N'$."Search Term 2"',          [Care Of]           NVARCHAR(255) N'$."Care Of"',          [Contact]           NVARCHAR(255) N'$."Contact"',          [Email]             NVARCHAR(255) N'$."Email"',          [Street 1]          NVARCHAR(255) N'$."Street 1"',          [House Number]      NVARCHAR(50)  N'$."House Number"',          [Street 2]          NVARCHAR(255) N'$."Street 2"',          [Street 3]          NVARCHAR(255) N'$."Street 3"',          [Street 4]          NVARCHAR(255) N'$."Street 4"',          [Street 5]          NVARCHAR(255) N'$."Street 5"',          [PO Box]            NVARCHAR(100) N'$."PO Box"',          [Suite]             NVARCHAR(100) N'$."Suite"',          [Building]          NVARCHAR(100) N'$."Building"',          [Floor]             NVARCHAR(100) N'$."Floor"',          [Room]              NVARCHAR(100) N'$."Room"',          [Unit]              NVARCHAR(100) N'$."Unit"',          [Mail Stop]         NVARCHAR(100) N'$."Mail Stop"',          [Unloading]         NVARCHAR(100) N'$."Unloading Point"',          [Mail Code]         NVARCHAR(100) N'$."Mail Code"',          [Record Type]       NVARCHAR(100) N'$."Record Type"',          [ROR ID]            NVARCHAR(255) N'$."ROR ID"',          [LEI ID]            NVARCHAR(100) N'$."LEI ID"',          [Flag for Review]   BIT           N'$."Flag for Review"',          [Flag Reason]       NVARCHAR(500) N'$."Flag Reason"'      );        ------------------------------------------------------------------      -- Dynamic SQL: only the schema name is spliced in.      -- SPACE(0) is used instead of a quoted empty string so the dynamic      -- text contains no nested quotes.      ------------------------------------------------------------------      DECLARE @sql NVARCHAR(MAX) = N'      MERGE ' + @tgt + N' AS tgt      USING #src AS src         ON tgt.Customer = src.Customer        AND tgt.[code] LIKE @pat ESCAPE @esc      WHEN MATCHED THEN UPDATE SET          tgt.[Name 1]            = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 1])), SPACE(0)),            tgt.[Name 1]),          tgt.[Name 2]            = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 2])), SPACE(0)),            tgt.[Name 2]),          tgt.[Name 3]            = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 3])), SPACE(0)),            tgt.[Name 3]),          tgt.[Name 4]            = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 4])), SPACE(0)),            tgt.[Name 4]),          tgt.[Domain]            = COALESCE(NULLIF(LTRIM(RTRIM(src.[Domain])), SPACE(0)),            tgt.[Domain]),          tgt.[Department Domain] = COALESCE(NULLIF(LTRIM(RTRIM(src.[Department Domain])), SPACE(0)), tgt.[Department Domain]),          tgt.[Search Term 1]     = COALESCE(NULLIF(LTRIM(RTRIM(src.[Search Term 1])), SPACE(0)),     tgt.[Search Term 1]),          tgt.[Search Term 2]     = COALESCE(NULLIF(LTRIM(RTRIM(src.[Search Term 2])), SPACE(0)),     tgt.[Search Term 2]),          tgt.[Care Of]           = COALESCE(NULLIF(LTRIM(RTRIM(src.[Care Of])), SPACE(0)),           tgt.[Care Of]),          tgt.[Contact]           = COALESCE(NULLIF(LTRIM(RTRIM(src.[Contact])), SPACE(0)),           tgt.[Contact]),          tgt.[Email]             = COALESCE(NULLIF(LTRIM(RTRIM(src.[Email])), SPACE(0)),             tgt.[Email]),          tgt.[Street 1]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 1])), SPACE(0)),          tgt.[Street 1]),          tgt.[House Number]      = COALESCE(NULLIF(LTRIM(RTRIM(src.[House Number])), SPACE(0)),      tgt.[House Number]),          tgt.[Street 2]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 2])), SPACE(0)),          tgt.[Street 2]),          tgt.[Street 3]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 3])), SPACE(0)),          tgt.[Street 3]),          tgt.[Street 4]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 4])), SPACE(0)),          tgt.[Street 4]),          tgt.[Street 5]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 5])), SPACE(0)),          tgt.[Street 5]),          tgt.[PO Box]            = COALESCE(NULLIF(LTRIM(RTRIM(src.[PO Box])), SPACE(0)),            tgt.[PO Box]),          tgt.[Suite]             = COALESCE(NULLIF(LTRIM(RTRIM(src.[Suite])), SPACE(0)),             tgt.[Suite]),          tgt.[Building]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Building])), SPACE(0)),          tgt.[Building]),          tgt.[Floor]             = COALESCE(NULLIF(LTRIM(RTRIM(src.[Floor])), SPACE(0)),             tgt.[Floor]),          tgt.[Room]              = COALESCE(NULLIF(LTRIM(RTRIM(src.[Room])), SPACE(0)),              tgt.[Room]),          tgt.[Unit]              = COALESCE(NULLIF(LTRIM(RTRIM(src.[Unit])), SPACE(0)),              tgt.[Unit]),          tgt.[Mail Stop]         = COALESCE(NULLIF(LTRIM(RTRIM(src.[Mail Stop])), SPACE(0)),         tgt.[Mail Stop]),          tgt.[Unloading]         = COALESCE(NULLIF(LTRIM(RTRIM(src.[Unloading])), SPACE(0)),         tgt.[Unloading]),          tgt.[Mail Code]         = COALESCE(NULLIF(LTRIM(RTRIM(src.[Mail Code])), SPACE(0)),         tgt.[Mail Code]),          tgt.[Record Type]       = LTRIM(RTRIM(src.[Record Type])),          tgt.[ROR ID]            = LTRIM(RTRIM(src.[ROR ID])),          tgt.[LEI ID]            = LTRIM(RTRIM(src.[LEI ID])),          tgt.[Flag for Review]   = src.[Flag for Review],          tgt.[Flag Reason]       = src.[Flag Reason];';        EXEC sp_executesql @sql, N'@pat NVARCHAR(60), @esc NCHAR(1)', @pat = @pat, @esc = @esc;        DROP TABLE #src;  END;  